const WEIGHTS={
 "First notice & onboarding":{reach:15,vol:20,rate:25,nom:10,toll:20,oral:10},
 "Bills & transactional":{reach:15,vol:30,rate:30,nom:5,toll:10,oral:10},
 "Hardship & debt support":{reach:10,vol:20,rate:30,nom:5,toll:15,oral:20},
 "Awareness & behaviour change":{reach:30,vol:15,rate:10,nom:25,toll:15,oral:5},
 "Enforcement & compliance":{reach:15,vol:20,rate:25,nom:5,toll:25,oral:10},
};
const SCENARIOS=Object.keys(WEIGHTS), CORRIDORS=Object.keys(DATA);
function compute(corridor,scenario){
  const rows=DATA[corridor],W=WEIGHTS[scenario];
  const reach=rows.map(r=>r[1]),low=rows.map(r=>r[2]),nom=rows.map(r=>r[3]),vol=rows.map(r=>r[1]*r[2]);
  const maxReach=Math.max(...reach),maxVol=Math.max(...vol),maxLow=Math.max(...low),minLow=Math.min(...low),maxNom=Math.max(...nom);
  const lnFloor=Math.log(0.001),lnMax=Math.log(maxReach);
  return rows.map((r,i)=>{
    const L=LANG[r[0]];
    const nr=reach[i]/maxReach,nv=vol[i]/maxVol,nrate=low[i]/maxLow,nn=maxNom>0?nom[i]/maxNom:0,nt=L.toll/5,no=L.oral/5;
    const score=W.reach*nr+W.vol*nv+W.rate*nrate+W.nom*nn+W.toll*nt+W.oral*no;
    let reachLog=1+4*(Math.log(Math.max(reach[i],0.001))-lnFloor)/(lnMax-lnFloor);reachLog=Math.max(1,Math.min(5,reachLog));
    const commercial=0.45*reachLog+0.30*L.nat+0.25*L.chan;
    const profNeed=maxLow===minLow?3:1+4*(low[i]-minLow)/(maxLow-minLow);
    const social=0.35*profNeed+0.30*L.pref+0.20*L.toll+0.15*L.emerg;
    const gap=commercial-social;
    let read="agree"; if(gap<=-0.5)read="social"; else if(gap>=0.5)read="comm";
    let tier=3; if(score>=55)tier=1; else if(score>=35)tier=2;
    return {lang:r[0],reach:reach[i],low:low[i],score,commercial,social,gap,read,tier,L};
  }).sort((a,b)=>b.score-a.score);
}
