function lgaRec(lang,le){
  if(OUTREACH_LANGS.includes(lang))return {r:"Outreach",c:"plan"};
  if(le>=1000)return {r:"Translate now",c:"p1"};
  if(le>=250)return {r:"Translate",c:"p2"};
  if(le>=50)return {r:"Consider",c:"prog"};
  return {r:"Low presence",c:"muted"};
}
function lgaRank(l){return Object.entries(l.l).map(([lang,v])=>{const rec=lgaRec(lang,v[1]);return {lang,sp:v[0],le:v[1],pct:+(v[1]/l.pop*100).toFixed(2),r:rec.r,c:rec.c};}).sort((a,b)=>b.le-a.le);}
function areaResolve(token){
  if(token&&token.indexOf('lga:')===0){const l=LGA_DETAIL.find(x=>x.n===token.slice(4));if(!l)return null;
    return {kind:'lga',label:l.n,state:l.st,corridor:STATE_CORR[l.st],sub:`whole of ${l.n} LGA · pop ${l.pop.toLocaleString()}`,pop:l.pop,cald:Math.round(l.cald*100),rank:lgaRank(l)};}
  const a=AREA[token];if(!a)return null;
  return {kind:'pc',label:a.s,state:a.st,corridor:STATE_CORR[a.st],sub:`${token} · ${a.st} corridor`,cald:a.cald,lim:a.lim,groups:a.l.map(([name,prop])=>({portal:ABS2LANG[name]||name,abs:name,prop}))};
}
function areaTokenLangs(token,n){const r=areaResolve(token);if(!r)return [];
  if(r.kind==='lga')return r.rank.filter(x=>x.r==='Translate now'||x.r==='Translate').map(x=>x.lang).filter(l=>LANG[l]).slice(0,n||6);
  const out=[];r.groups.forEach(g=>{if(LANG[g.portal]&&!out.includes(g.portal))out.push(g.portal);});return out.slice(0,n||6);}
function areaOptions(corridor){const st=Object.keys(STATE_CORR).find(k=>STATE_CORR[k]===corridor);
  const lgas=LGA_DETAIL.filter(l=>l.st===st).map(l=>({v:'lga:'+l.n,t:l.n+' (whole LGA)'}));
  const subs=Object.keys(AREA).filter(pc=>AREA[pc].st===st).map(pc=>({v:pc,t:AREA[pc].s+' · '+pc}));
  return {lgas,subs};}
