const DESIGN_PRINCIPLES=[
 {n:"01",name:"Approachability",line:"Remove what stops willing people engaging.",d:"Most CALD audiences want to do the right thing — the work is to make the system safe, legitimate, recognising, assured and supported at every touchpoint, so intent can become action.",conds:["Safe — no fear of penalty or judgement","Legitimate — clearly real and official, not a scam","Recognising — sees who they are; in-language, culturally aware","Assured — confidence it worked and what's next","Supported — help is there when they hit a wall"]},
 {n:"02",name:"Amplification",line:"Activate the networks people already trust.",d:"Helping others navigate unfamiliar systems is already a social norm in CALD communities. The work is to equip the trusted people and organisations with something concrete to pass on — then step back.",conds:["Recognise the people communities already turn to","Give them shareable, in-language, accurate resources","Make helping easy and rewarded","Enable, don't lead — Transurban funds and equips, then steps back"]},
];
